  height: 210px;
  padding: 12px;
}

.cardTitle {
  font-size: 1.4rem;
  font-weight: 500;
  line-height: 1.3;
  letter-spacing: -0.01em;
  white-space: pre-line;
  text-align: left;
}

.cardTitleSmall {
  font-size: 0.9rem;
  line-height: 1.2;
}

.circle {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background-color: rgba(255, 255, 255, 0.25);
  margin-bottom: 12px;
}

.circleSmall {
  width: 20px;
  height: 20px;
  margin-bottom: 6px;
}

.circleExpanded {
  width: 140px;
  height: 140px;
  border-radius: 50%;
  background-color: rgba(255, 255, 255, 0.25);
  margin-bottom: 26px;
  align-self: center;
}

.popupPositioner {
  position: fixed;
  inset: 0 0 40px 0;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

.expandedCard {
  overflow: hidden;
  will-change: transform;
  width: 400px;
  min-height: 500px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-end;
  gap: 12px;
  pointer-events: auto;
}

