  white-space: pre-line;
  text-align: left;
}

.expandedDescription {
  font-size: var(--font-size-base, 1rem);
  line-height: 1.8;
  margin: 0;
  opacity: 0.8;
}

.mobileStack {
  position: relative;
  width: 100%;
  max-width: 320px;
  height: 420px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.mobileCard {
  position: absolute;
  width: 300px;
  height: 400px;
  border-radius: 20px;
  padding: 24px;
  padding-bottom: 56px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-end;
  cursor: grab;
  touch-action: pan-y;
  user-select: none;
}

.mobileCard:active {
  cursor: grabbing;
}

.mobileDescription {
  font-size: var(--font-size-sm, 0.875rem);
  line-height: 1.6;
  margin: 12px 0 0 0;
  opacity: 0.85;
}

.swipeHint {
  position: absolute;
  bottom: 24px;
  left: 0;
  right: 0;
  display: flex;
  justify-content: center;
  pointer-events: none;
}

.swipeHint span {
  font-size: var(--font-size-xs, 0.75rem);
  opacity: 0.5;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

"use client";

import { motion, type PanInfo, useReducedMotion } from "motion/react";
import { useState } from "react";
import styles from "./expandable-card-spread.module.css";

type CardData = {
  id: number;
  title: string;
  color: string;
  textColor?: string;
  description: string;
};

type MobileStackProps = {
  cards: CardData[];
};

const SWIPE_THRESHOLD = 100;

export function MobileStack({ cards }: MobileStackProps) {
  const [frontIndex, setFrontIndex] = useState(0);
  const prefersReducedMotion = useReducedMotion();

  const handleDragEnd = (_: unknown, info: PanInfo) => {
    if (Math.abs(info.offset.x) > SWIPE_THRESHOLD) {
      setFrontIndex((prev) => (prev + 1) % cards.length);
    }
  };

  return (
    <div className={styles.container}>
      <div className={styles.mobileStack}>
        {cards.map((card, i) => {
          const stackPosition = (i - frontIndex + cards.length) % cards.length;
          const isTopCard = stackPosition === 0;

          return (
            <motion.div
              animate={{
                scale: 1 - stackPosition * 0.03,
                x: stackPosition * (13 - stackPosition),
                y: stackPosition * 6,
                rotate: Math.sqrt(stackPosition) * 3,
              }}
              className={styles.mobileCard}
              drag={isTopCard ? "x" : false}
              dragConstraints={{ left: 0, right: 0 }}
              dragElastic={1}
              key={card.id}
              layout
              onDragEnd={isTopCard ? handleDragEnd : undefined}
              style={{
                backgroundColor: card.color,
                color: card.textColor || "#ffffff",
                zIndex: cards.length - stackPosition,
                cursor: isTopCard ? "grab" : "auto",
              }}
              transition={prefersReducedMotion ? { duration: 0 } : { type: "spring", stiffness: 300, damping: 25 }}
              whileDrag={prefersReducedMotion ? { cursor: "grabbing" } : { cursor: "grabbing", scale: 1.02 }}
            >
              <div className={styles.circle} />
              <h3 className={styles.cardTitle}>{card.title}</h3>
              <p className={styles.mobileDescription}>{card.description}</p>
            </motion.div>
          );
        })}
      </div>
    </div>
  );
}

